const payload = $input.first().json;
const obj = payload.object;

let channel = '', senderId = '', phone = '', name = '', text = '', messageId = '';

if (obj === 'whatsapp_business_account') {
  const value = payload.entry?.[0]?.changes?.[0]?.value;
  if (!value?.messages) return [];
  const msg = value.messages[0];
  const contact = value.contacts?.[0];
  channel = 'whatsapp';
  senderId = msg.from;
  phone = msg.from;
  name = contact?.profile?.name || '';
  text = msg?.text?.body || '';
  messageId = msg.id;
} else if (obj === 'page') {
  // Ignorar leadgen events (manejados en workflow 1)
  const changes = payload.entry?.[0]?.changes || [];
  if (changes.some(c => c.field === 'leadgen')) return [];
  const messaging = payload.entry?.[0]?.messaging?.[0];
  if (!messaging?.message?.text) return [];
  channel = 'facebook';
  senderId = messaging.sender.id;
  text = messaging.message.text;
  messageId = messaging.message.mid;
} else if (obj === 'instagram') {
  const messaging = payload.entry?.[0]?.messaging?.[0];
  if (!messaging?.message?.text) return [];
  channel = 'instagram';
  senderId = messaging.sender.id;
  text = messaging.message.text;
  messageId = messaging.message.mid;
} else {
  return [];
}

if (!text) return [];
return [{ json: { channel, senderId, phone, name, text, messageId } }];

const contactSearch = $input.first().json;
const contact = contactSearch.contacts?.[0] || null;
const msgData = $('Parsear canal y mensaje').item.json;

// Recuperar historial desde notas del contacto (campo customField)
let history = [];
if (contact) {
  const histField = contact.customField?.find(f => f.key === 'chat_history');
  if (histField?.value) {
    try { history = JSON.parse(histField.value); } catch(e) { history = []; }
  }
}

// Limitar a últimas 10 interacciones (20 mensajes)
if (history.length > 20) history = history.slice(-20);

return [{ json: {
  ...msgData,
  contactId: contact?.id || null,
  opportunityId: contact?.customField?.find(f => f.key === 'opportunity_id')?.value || null,
  currentStage: contact?.customField?.find(f => f.key === 'pipeline_stage')?.value || 'contactado',
  history,
  isNewContact: !contact
}}];

