const resp = $input.first().json;
const assistantText = resp.content?.[0]?.text || '';

// Extraer JSON de acción si existe
const jsonMatch = assistantText.match(/```json\s*(\{[\s\S]*?\})\s*```/);
let action = null;
if (jsonMatch) {
  try { action = JSON.parse(jsonMatch[1]); } catch(e) {}
}

// Limpiar el JSON del texto antes de enviar al usuario
const cleanText = assistantText.replace(/```json[\s\S]*?```/g, '').trim();

// Actualizar historial
const prevData = $('Recuperar historial de conversación').item.json;
const newHistory = [
  ...prevData.history,
  { role: 'user', content: prevData.text },
  { role: 'assistant', content: assistantText }
];
const trimmedHistory = newHistory.length > 20 ? newHistory.slice(-20) : newHistory;

return [{ json: {
  ...prevData,
  assistantText,
  cleanText,
  action,
  newHistory: trimmedHistory
}}];

